#include <bits/stdc++.h>
using namespace std;

using pii = pair<int, int>;

int fx[] = {1, -1, 0, 0};
int fy[] = {0, 0, 1, -1};
int d[210][210];
bool vis[210][210];
int aa, bb;

int bfs(int sx, int sy) {
    memset(vis, 0, sizeof(vis));
    memset(d, 0, sizeof(d));

    queue<pii> q;
    q.push({sx, sy});
    vis[sx][sy] = true;

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        if (x == aa && y == bb)
            return d[x][y];

        for (int k = 0; k < 4; ++k) {
            int tx = x + fx[k];
            int ty = y + fy[k];

            if (tx >= 0 && tx < 210 && ty >= 0 && ty < 210 &&
                !vis[tx][ty]) {
                vis[tx][ty] = true;
                d[tx][ty] = d[x][y] + 1;
                q.push({tx, ty});
            }
        }
    }

    return -1;
}

int main() {
    int a, b;
    cin >> a >> b;
    a += 100;
    b += 100;

    cin >> aa >> bb;
    aa += 100;
    bb += 100;

    if (aa != a && bb != b) {
        cout << 2 * (bfs(a, b) + 2);
    } else {
        cout << max(8, 6 + bfs(a, b) * 2);
    }

    return 0;
}

